class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.strip().splitlines()]

    def _connects(self, player, grid):
        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        stack = [(0, c) for c in range(cols) if grid[0][c] == player]
        seen = set(stack)
        while stack:
            r, c = stack.pop()
            if r == rows - 1:
                return True
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1), (-1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen \
                        and grid[nr][nc] == player:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return False

    def get_winner(self):
        if self._connects("O", self.board):
            return "O"
        transposed = [list(col) for col in zip(*self.board)]
        if self._connects("X", transposed):
            return "X"
        return ""
